// ── KST 일요일 0시 기준 현재 회차 자동 계산 ──────────────────────────────────
function getCurrentRound() {
  const kst = new Date(Date.now() + 9 * 60 * 60 * 1000);
  const base = new Date("2002-12-08T00:00:00Z");
  return Math.floor((kst - base) / (7 * 24 * 60 * 60 * 1000)) + 1;
}
const CURRENT_ROUND = getCurrentRound();

// ── 번호 색상 (실제 로또 공 색상) ─────────────────────────────────────────────
function ballStyle(n) {
  if (n <= 10) return { bg: "#FBC400", text: "#1a1000", glow: "#FBC40066" };
  if (n <= 20) return { bg: "#69C8F2", text: "#0a2030", glow: "#69C8F266" };
  if (n <= 30) return { bg: "#FF7272", text: "#fff",    glow: "#FF727266" };
  if (n <= 40) return { bg: "#BBBBBB", text: "#1a1a1a", glow: "#BBBBBB44" };
  return             { bg: "#B0D840", text: "#1a3000",  glow: "#B0D84066" };
}

// ── 통계 계산 ─────────────────────────────────────────────────────────────────
function buildStats(history) {
  const total = {}, recent20 = {}, gap = {};
  for (let i = 1; i <= 45; i++) { total[i] = 0; recent20[i] = 0; gap[i] = history.length; }
  history.forEach(({ numbers }, idx) => {
    numbers.forEach(n => {
      total[n]++;
      if (idx >= history.length - 20) recent20[n]++;
      gap[n] = history.length - 1 - idx;
    });
  });
  // 연속 번호 패턴 계산
  const consecutive = {};
  for (let i = 1; i <= 45; i++) consecutive[i] = 0;
  history.forEach(({ numbers }) => {
    for (let i = 0; i < numbers.length - 1; i++) {
      if (numbers[i + 1] - numbers[i] === 1) {
        consecutive[numbers[i]]++;
        consecutive[numbers[i + 1]]++;
      }
    }
  });
  // 가중치: 최근20회 60% + 전체 40% + 미출현 보너스
  const weights = {};
  for (let i = 1; i <= 45; i++) {
    const g = total[i] / (history.length * 6);
    const r = recent20[i] / (Math.min(history.length, 20) * 6);
    const gapBonus = gap[i] > 10 ? 0.002 : 0;
    weights[i] = g * 0.4 + r * 0.6 + gapBonus + 0.001;
  }
  return { total, recent20, weights, gap, consecutive };
}

// ── 실제 200회차 통계 기반 홀짝 분포 ─────────────────────────────────────────
// 홀0:1.5% / 홀1:12.5% / 홀2:25.5% / 홀3:23.5% / 홀4:23.0% / 홀5:11.0% / 홀6:3.0%
const ODD_WEIGHTS = [1.5, 12.5, 25.5, 23.5, 23.0, 11.0, 3.0];

function pickOddCount() {
  const r = Math.random() * 100;
  let acc = 0;
  for (let i = 0; i <= 6; i++) {
    acc += ODD_WEIGHTS[i];
    if (r < acc) return i;
  }
  return 3;
}

// ── 통계 가중치 기반 번호 생성 (홀짝 비율 실제 확률 반영) ──────────────────────
function generateNumbers(stats) {
  const targetOdd = pickOddCount();
  const odds  = []; // 홀수 풀
  const evens = []; // 짝수 풀

  // 가중치 풀 분리
  for (let i = 1; i <= 45; i++) {
    const w = Math.max(1, Math.round(stats.weights[i] * 10000));
    const arr = i % 2 !== 0 ? odds : evens;
    for (let j = 0; j < w; j++) arr.push(i);
  }

  function pickFrom(pool, count, exclude) {
    const picked = new Set();
    let tries = 0;
    while (picked.size < count && tries < 10000) {
      const n = pool[Math.floor(Math.random() * pool.length)];
      if (!exclude.has(n)) picked.add(n);
      tries++;
    }
    return [...picked];
  }

  const result = new Set();
  const oddNums  = pickFrom(odds,  targetOdd,       result);
  oddNums.forEach(n => result.add(n));
  const evenNums = pickFrom(evens, 6 - targetOdd,   result);
  evenNums.forEach(n => result.add(n));

  // 혹시 부족하면 나머지 채움 (엣지케이스)
  if (result.size < 6) {
    const fallback = [];
    for (let i = 1; i <= 45; i++) fallback.push(i);
    while (result.size < 6) {
      result.add(fallback[Math.floor(Math.random() * fallback.length)]);
    }
  }

  return [...result].sort((a, b) => a - b);
}

// ── 1등 금액 포맷 ─────────────────────────────────────────────────────────────
function fmtPrize(n) {
  if (!n) return "-";
  const b = Math.floor(n / 100000000);
  const m = Math.floor((n % 100000000) / 10000000);
  if (b > 0) return `${b}억${m > 0 ? " " + m + "천만" : ""}원`;
  return `${Math.floor(n / 10000)}만원`;
}

// ── Ball 컴포넌트 ─────────────────────────────────────────────────────────────
function Ball({ n, size = 52, delay = 0, animate = false, dim = false }) {
  const { bg, text, glow } = ballStyle(n);
  return (
    <div style={{
      width: size, height: size, borderRadius: "50%", flexShrink: 0,
      display: "flex", alignItems: "center", justifyContent: "center",
      fontSize: size * 0.38, fontFamily: "'Bebas Neue', cursive", fontWeight: 700,
      color: text, letterSpacing: 0.5,
      background: `radial-gradient(circle at 33% 28%, ${bg}ff, ${bg}cc)`,
      boxShadow: dim ? "none" : `0 0 16px ${glow}, 0 5px 15px rgba(0,0,0,0.6), inset 0 2px 4px rgba(255,255,255,0.4)`,
      opacity: dim ? 0.25 : 1,
      border: `2px solid ${bg}aa`,
      transform: animate ? "scale(0) rotate(-20deg)" : "scale(1)",
      animation: animate ? `ballPop 0.5s cubic-bezier(0.34,1.6,0.64,1) ${delay}s forwards` : "none",
    }}>{n}</div>
  );
}

